import{_ as a,o as t,c as l,a4 as h}from"./chunks/framework.DzJZdBQK.js";const _=JSON.parse('{"title":"写作课作业-107","description":"","frontmatter":{"date":"2021-02-26T23:02:12","title":"写作课作业-107","categories":["写作","作业","区块链小白书"],"tags":["写作","作业","区块链小白书"]},"headers":[{"level":2,"title":"2W1H","slug":"_2w1h","link":"#_2w1h","children":[{"level":3,"title":"What","slug":"what","link":"#what","children":[]},{"level":3,"title":"Why","slug":"why","link":"#why","children":[]},{"level":3,"title":"How","slug":"how","link":"#how","children":[]}]},{"level":2,"title":"知识点","slug":"知识点","link":"#知识点","children":[{"level":3,"title":"我的思考","slug":"我的思考","link":"#我的思考","children":[]}]}],"relativePath":"posts/homework/107.md","filePath":"posts/homework/107.md"}'),o={name:"posts/homework/107.md"};function r(i,e,n,p,s,d){return t(),l("div",null,[...e[0]||(e[0]=[h('<blockquote><p>《区块链小白书》之《比特币 3.比特币其实不可能替代法币》</p></blockquote><h2 id="_2w1h" tabindex="-1">2W1H <a class="header-anchor" href="#_2w1h" aria-label="Permalink to &quot;2W1H&quot;">​</a></h2><h3 id="what" tabindex="-1">What <a class="header-anchor" href="#what" aria-label="Permalink to &quot;What&quot;">​</a></h3><p>比特币不可能替代法币</p><h3 id="why" tabindex="-1">Why <a class="header-anchor" href="#why" aria-label="Permalink to &quot;Why&quot;">​</a></h3><p>日常生活中人们需要的货币必须是价格相对稳定的。而比特币的价格波动剧烈。</p><h3 id="how" tabindex="-1">How <a class="header-anchor" href="#how" aria-label="Permalink to &quot;How&quot;">​</a></h3><p>通过人们对新生事物的两极分化，引出一部分人对比特币寄予了过分的期待——成为法币。而后说法币需要价格相对稳定，而比特币在未来相当长的一段时间里，比特币的价格不可能稳定，而且波动剧烈。</p><p>当比特币价格趋于稳定时，她还成为货币之一，但仍不会替他所有法币。</p><h2 id="知识点" tabindex="-1">知识点 <a class="header-anchor" href="#知识点" aria-label="Permalink to &quot;知识点&quot;">​</a></h2><p>对于新生事物，人们总是过于两极分化，要么断然拒绝接受，要么对它寄予过分的期待。</p><p>长期来看，即便比特币的价格因为绝大多数人都接受而趋于稳定，它也只不过会成为地球上众多货币之中的一个而已，仍旧不可能替代所有法币。</p><h3 id="我的思考" tabindex="-1">我的思考 <a class="header-anchor" href="#我的思考" aria-label="Permalink to &quot;我的思考&quot;">​</a></h3><p>新生事物，意味着变化，时常说要拥抱变化，那在对待区块链，AI等方面就要保持好奇心，在好奇心的基础上适当的做配置（比如购置资产，学习相关技能），降低系统风险。</p><p>现在比特币的价格还在剧烈的涨跌当中，远远还未趋于稳定，也从另一个方面说明人们对比特币的共识还没有达成，但比特币的从发币到现在整体价格在上涨，说明达成共识的人越来越多，不知道理解正不正确？是否也就能说持有比特币的人数越多，持有比特币的数目越多，比特币的价格越快趋于稳定？</p><hr><p>欢迎联系我</p><p>微信号 ：Crazy_Airhead</p><p>Mixin ID : 1091586</p><p>定投课堂邀请码：6DYMBFP061</p><p>李笑来写作课邀请码：38MDGFYZK8</p><p>水龙头邀请码：FDJQHJ</p>',22)])])}const u=a(o,[["render",r]]);export{_ as __pageData,u as default};
